import{_ as t,c as r,o as n,ag as o}from"./chunks/framework.B-XtCDNB.js";const g=JSON.parse('{"title":"Project Documentation","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/index.md","filePath":"en/projects/index.md"}'),a={name:"en/projects/index.md"};function i(s,e,l,p,d,c){return n(),r("div",null,[...e[0]||(e[0]=[o(`<h1 id="project-documentation" tabindex="-1">Project Documentation <a class="header-anchor" href="#project-documentation" aria-label="Permalink to &quot;Project Documentation&quot;">​</a></h1><p>Choose a project type that interests you to dive deep into different implementations of Verdure Assistant.</p><h2 id="🚀-project-overview" tabindex="-1">🚀 Project Overview <a class="header-anchor" href="#🚀-project-overview" aria-label="Permalink to &quot;🚀 Project Overview&quot;">​</a></h2><p>Verdure Assistant provides four different project implementations, each optimized for specific use cases and platforms.</p><h3 id="project-comparison" tabindex="-1">Project Comparison <a class="header-anchor" href="#project-comparison" aria-label="Permalink to &quot;Project Comparison&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Project Type</th><th>Platform Support</th><th>Difficulty</th><th>Use Cases</th><th>Learning Order</th></tr></thead><tbody><tr><td><strong><a href="/en/projects/console.html">Console Application</a></strong></td><td>Windows/Linux/macOS</td><td>⭐⭐</td><td>Core architecture, server deployment</td><td>1️⃣ First choice</td></tr><tr><td><strong><a href="/en/projects/winui.html">WinUI Desktop App</a></strong></td><td>Windows 10+</td><td>⭐⭐⭐</td><td>Windows desktop UI</td><td>2️⃣</td></tr><tr><td><strong><a href="/en/projects/api.html">API Service</a></strong></td><td>Windows/Linux/macOS</td><td>⭐⭐⭐⭐</td><td>Raspberry Pi robots, IoT integration</td><td>3️⃣</td></tr><tr><td><strong><a href="/en/projects/maui.html">MAUI Cross-platform</a></strong></td><td>Android/iOS/Windows/macOS</td><td>⭐⭐⭐⭐⭐</td><td>Mobile app development</td><td>4️⃣</td></tr></tbody></table><h2 id="📱-project-details" tabindex="-1">📱 Project Details <a class="header-anchor" href="#📱-project-details" aria-label="Permalink to &quot;📱 Project Details&quot;">​</a></h2><h3 id="console-application" tabindex="-1">Console Application <a class="header-anchor" href="#console-application" aria-label="Permalink to &quot;Console Application&quot;">​</a></h3><p><strong>Best starting choice</strong> - Ideal entry point for understanding core project architecture</p><ul><li>✅ <strong>Simple &amp; Direct</strong>: Command-line interface focusing on core functionality</li><li>✅ <strong>Cross-platform</strong>: Runs on all major platforms</li><li>✅ <strong>Learning-friendly</strong>: Clear code structure, easy to understand</li><li>✅ <strong>Quick setup</strong>: Minimal dependencies and configuration</li></ul><p><strong>Suitable for</strong>:</p><ul><li>.NET beginners</li><li>Developers wanting to understand project architecture</li><li>DevOps engineers needing server deployment</li></ul><p><strong><a href="/en/projects/console.html">Start learning Console project →</a></strong></p><hr><h3 id="winui-desktop-app" tabindex="-1">WinUI Desktop App <a class="header-anchor" href="#winui-desktop-app" aria-label="Permalink to &quot;WinUI Desktop App&quot;">​</a></h3><p><strong>Modern Windows app development</strong> - Experience the latest Windows application interface</p><ul><li>🖥️ <strong>Modern UI</strong>: Smooth interface based on WinUI 3</li><li>🎤 <strong>Visual interaction</strong>: Real-time voice waveform and status display</li><li>⚙️ <strong>Graphical configuration</strong>: No need to manually edit config files</li><li>🎨 <strong>Theme support</strong>: Automatic light/dark theme switching</li></ul><p><strong>Suitable for</strong>:</p><ul><li>Windows app developers</li><li>UI/UX designers</li><li>Desktop application users</li></ul><p><strong><a href="/en/projects/winui.html">Start learning WinUI project →</a></strong></p><hr><h3 id="api-service" tabindex="-1">API Service <a class="header-anchor" href="#api-service" aria-label="Permalink to &quot;API Service&quot;">​</a></h3><p><strong>Server-side development</strong> - Build powerful backend services</p><ul><li>🤖 <strong>IoT integration</strong>: Optimized for Raspberry Pi and embedded devices</li><li>📡 <strong>Real-time communication</strong>: WebSocket bidirectional communication</li><li>🌐 <strong>RESTful API</strong>: Standardized interface design</li><li>🔧 <strong>Device management</strong>: Complete device registration and monitoring</li></ul><p><strong>Suitable for</strong>:</p><ul><li>Backend developers</li><li>IoT/Hardware engineers</li><li>System architects</li></ul><p><strong><a href="/en/projects/api.html">Start learning API project →</a></strong></p><hr><h3 id="maui-cross-platform-app" tabindex="-1">MAUI Cross-platform App <a class="header-anchor" href="#maui-cross-platform-app" aria-label="Permalink to &quot;MAUI Cross-platform App&quot;">​</a></h3><p><strong>Mobile app development</strong> - One codebase, multiple platforms</p><ul><li>📱 <strong>Truly cross-platform</strong>: Android, iOS, Windows, macOS</li><li>🎨 <strong>Native experience</strong>: Platform-specific UI controls</li><li>🔄 <strong>Offline support</strong>: Local data storage and synchronization</li><li>🔐 <strong>Secure &amp; reliable</strong>: End-to-end encryption and permission management</li></ul><p><strong>Suitable for</strong>:</p><ul><li>Mobile app developers</li><li>Cross-platform technology enthusiasts</li><li>Developers wanting to master MAUI</li></ul><p><strong><a href="/en/projects/maui.html">Start learning MAUI project →</a></strong></p><h2 id="🎯-learning-recommendations" tabindex="-1">🎯 Learning Recommendations <a class="header-anchor" href="#🎯-learning-recommendations" aria-label="Permalink to &quot;🎯 Learning Recommendations&quot;">​</a></h2><h3 id="beginner-path" tabindex="-1">Beginner Path <a class="header-anchor" href="#beginner-path" aria-label="Permalink to &quot;Beginner Path&quot;">​</a></h3><ol><li><strong>Start with Console</strong>: Understand core concepts and architecture</li><li><strong>Move to WinUI</strong>: Learn user interface development</li><li><strong>Explore API</strong>: Master server-side development</li><li><strong>Challenge MAUI</strong>: Experience cross-platform development</li></ol><h3 id="experienced-developers" tabindex="-1">Experienced Developers <a class="header-anchor" href="#experienced-developers" aria-label="Permalink to &quot;Experienced Developers&quot;">​</a></h3><p>Choose directly based on your interests and needs:</p><ul><li><strong>Desktop app developers</strong> → <a href="/en/projects/winui.html">WinUI Project</a></li><li><strong>Backend/API developers</strong> → <a href="/en/projects/api.html">API Project</a></li><li><strong>Mobile app developers</strong> → <a href="/en/projects/maui.html">MAUI Project</a></li><li><strong>System administrators</strong> → <a href="/en/projects/console.html">Console Project</a></li></ul><h3 id="full-stack-learning" tabindex="-1">Full-stack Learning <a class="header-anchor" href="#full-stack-learning" aria-label="Permalink to &quot;Full-stack Learning&quot;">​</a></h3><p>If you want to master the entire technology stack, we recommend learning in this order:</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Console → API → WinUI → MAUI</span></span>
<span class="line"><span>  ↓       ↓       ↓        ↓</span></span>
<span class="line"><span>Core     Server   Desktop  Mobile</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h2 id="🛠️-development-environment" tabindex="-1">🛠️ Development Environment <a class="header-anchor" href="#🛠️-development-environment" aria-label="Permalink to &quot;🛠️ Development Environment&quot;">​</a></h2><p>All projects require the following basic environment:</p><ul><li><strong>.NET 9.0 SDK</strong> or higher</li><li><strong>Visual Studio 2022</strong> or <strong>Visual Studio Code</strong></li><li><strong>Git</strong> version control</li></ul><p>For additional requirements specific to each project, please refer to their detailed documentation.</p><h2 id="📚-related-resources" tabindex="-1">📚 Related Resources <a class="header-anchor" href="#📚-related-resources" aria-label="Permalink to &quot;📚 Related Resources&quot;">​</a></h2><ul><li><strong><a href="/en/guide/getting-started.html">Getting Started</a></strong> - 5-minute quick guide</li><li><strong><a href="/en/guide/environment-setup.html">Environment Setup</a></strong> - Development environment configuration</li><li><strong><a href="/en/guide/tech-stack.html">Tech Stack Introduction</a></strong> - Learn about technologies used</li><li><strong><a href="/en/guide/architecture.html">Project Architecture</a></strong> - Understand system design</li></ul><hr><p>Choose a project to start your Verdure Assistant learning journey! Each project has detailed documentation, sample code, and practical guidance.</p>`,51)])])}const u=t(a,[["render",i]]);export{g as __pageData,u as default};
